        for (int i = 0; i < K; i++) {
            a[i] = Integer.parseInt(st.nextToken()) - 1;
            starts[a[i]]++;
        }

        int maxT = K + N + 1;
        int V = (maxT + 1) * N + 2;
        int src = V - 2;
        int sink = V - 1;

        List<List<Edge>> g = new ArrayList<>();
        for (int i = 0; i < V; i++) {
            g.add(new ArrayList<>());
        }

        // Helper class for edges
        class Edge {
            int v, cap, cost;
            Edge rev;

            Edge(int v, int cap, int cost) {
                this.v = v;
                this.cap = cap;
                this.cost = cost;
            }
        }

        // Method to add edges
        BiConsumer<Integer, Edge> addEdge = (u, e) -> {
            g.get(u).add(e);
        };

        // Add edge method
        void addEdge(int u, int v, int cap, int cost) {
            Edge forward = new Edge(v, cap, cost);
            Edge backward = new Edge(u, 0, -cost);
            forward.rev = backward;
            backward.rev = forward;
            g.get(u).add(forward);
            g.get(v).add(backward);
